  c -> recovery_depth = owner -> recovery_depth;
  c -> sources = owner -> sources;
  c -> declaration_produced = owner -> declaration_produced;
  c -> source_facts = owner -> source_facts;
  c -> source_occurrences = owner -> source_occurrences;
